#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int placed=0; placed<n-2; placed++){
        int target = placed+1;
        int pos = -1;
        for(int i=placed;i<n;i++) if(p[i]==target){pos=i;break;}
        if(pos==placed) continue;

        // Step 1: Move element from pos to position n-1
        if(pos != n-1){
            // We want to move p[pos] to position n-1
            // Operation (x, y): result = [suffix y][middle][prefix x]
            // p[pos] is at index pos. We want it at n-1.
            // If we put it in the prefix (first x elements), it goes to the end.
            // Specifically, p[i] for i in [0..x-1] goes to position (n-x)+i
            // So p[pos] goes to position (n-x)+pos = n-1 => x = pos+1
            // Need x + y < n => pos+1+y < n, and y >= 1 => y=1 works if pos+2 <= n-1 => pos <= n-3
            // Also need middle to exist: n - x - y >= 0 (can be 0? no, middle can be empty but x+y<n means middle >= 1)
            if(pos <= n-3){
                int x = pos+1, y = 1;
                apply(x, y);
            } else {
                // pos == n-2, need to move to n-1
                // x = n-1, y >= 1, x+y < n => n-1+y < n => y < 1, impossible
                // Alternative: use y = n-1-pos = 1, but then p[pos] is first of suffix, goes to position 0
                // Use y=2: suffix is p[n-2], p[n-1]. Our element at n-2 goes to position 0.
                // x=1, y=2, x+y=3<n (need n>3). Then element goes to pos 0, then we handle it next.
                if(n > 3){
                    apply(1, 2);
                    // element moved to position 0, now use x=1, y=1 to move pos 0 to end
                    apply(1, 1);
                } else {
                    // n==3, pos=1, want to move to pos 2
                    apply(1, 1);
                }
            }
            pos = n-1;
        }

        // Step 2: Move element from position n-1 to position 'placed'
        // Use y=1: suffix = [p[n-1]], goes to position 0. Then x = placed.
        // Result: [p[n-1]] + [p[placed]..p[n-2]] + [p[0]..p[placed-1]]
        // p[n-1] goes to position 0, but we want position 'placed'.
        // Use x = n-1-placed, y=1: p[n-1] at pos 0, prefix of size n-1-placed at end.
        // Actually: y=1 puts our element at pos 0. x=n-1-placed, middle=placed elements.
        // Hmm, need placed==0 case: x=n-1-0=n-1, y=1, x+y=n not <n. Use x=n-2,y=1 => element at pos 0, that's placed=0. Done? No, placed=0 means pos 0 is correct.
        if(placed == 0){
            apply(n-2, 1);
        } else {
            apply(placed, 1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
